 	}
 }
 // ( SOLUZIONE 2024-09-11
+
+/// Parte C++ della primitiva rw_upgrade()
+extern "C" void c_rw_upgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_upgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r);
+
+	if (!rp) {
+		flog(LOG_WARN, "rw_upgrade(%d): processo non possiede il lock", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state != RW_READER) {
+		flog(LOG_WARN, "rw_upgrade(%d): lock non in stato RW_READER", rw);
+		c_abort_p();
+		return;
+	}
+
+	rp->state = RW_UPGRADED;
+	r->nreaders--;
+
+	if (r->nreaders > 0 || r->w_writers) {
+		inserimento_lista(r->w_writers, esecuzione);
+		schedulatore();
+	} else {
+		r->writer = esecuzione->id;
+	}
+}
+
+/// Parte C++ della primitiva rw_downgrade()
+extern "C" void c_rw_downgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_downgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r);
+
+	if (!rp) {
+		flog(LOG_WARN, "rw_downgrade(%d): processo non possiede il lock", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state == RW_UPGRADED) {
+		rp->state = RW_READER;
+		r->writer = 0;
+		r->nreaders++;
+	} else if (rp->state == RW_WRITER) {
+		r->writer = 0;
+		rp->state = RW_NONE;
+		rp->r = nullptr;
+	} else if (rp->state == RW_READER) {
+		r->nreaders--;
+		rp->state = RW_NONE;
+		rp->r = nullptr;
+	}
+
+	if (rp->state == RW_NONE) {
+		des_proc* p = rimozione_lista(r->w_readers);
+		if (p) {
+			des_proc_rw *rp2 = rw_proc_find(r, p);
+			rp2->state = RW_READER;
+			r->nreaders++;
+			inserimento_lista(pronti, p);
+			schedulatore();
+		} else {
+			p = rimozione_lista(r->w_writers);
+			if (p) {
+				r->writer = p->id;
+				inserimento_lista(pronti, p);
+				schedulatore();
+			}
+		}
+	}
+}
+
 //   SOLUZIONE 2024-09-11 )
 //   ESAME 2024-09-11 )

